      A_SPAN = 3800,
      A_AT = k => 200 + k * A_SPAN,
      A_X = k => 440 + k * 440,
      NITS = [
        "nit: rename this",
        "nit: typo",
        "nit: extract helper",
        "nit: blank line",
        "nit: reword comment",
        "nit: early return",
        "nit: sort imports",
        "nit: one more test",
        "nit: naming again",
        "nit: inline this",
        "nit: fix wording",
        "nit: lgtm, but…",
      ],
      ROUND = (A_SPAN - 400) / (NITS.length / A_N),
      B_N = 30,
